package com.procurement.quotationcomparison.entity;import com.procurement.vendor.entity.Vendor;import com.procurement.vendorquotation.entity.VendorQuotation;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name="quotation_comparison_lines",uniqueConstraints=@UniqueConstraint(columnNames={"comparison_id","vendor_quotation_id"}))@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class QuotationComparisonLine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="comparison_line_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="comparison_id",nullable=false)private QuotationComparison comparison;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_quotation_id",nullable=false)private VendorQuotation vendorQuotation;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@Column(name="price_score",precision=8,scale=2)private BigDecimal priceScore;@Column(name="technical_score",precision=8,scale=2)private BigDecimal technicalScore;@Column(name="quality_score",precision=8,scale=2)private BigDecimal qualityScore;@Column(name="delivery_score",precision=8,scale=2)private BigDecimal deliveryScore;@Column(name="warranty_score",precision=8,scale=2)private BigDecimal warrantyScore;@Column(name="commercial_score",precision=8,scale=2)private BigDecimal commercialScore;@Column(name="overall_score",precision=8,scale=2)private BigDecimal overallScore;@Column(name="rank_order")private Integer rank;@Builder.Default private Boolean recommended=false;@Column(length=500)private String remarks;}
